-- 20260709111050_2ac84621-9757-428d-a9a1-b7f0f03a9d98.sql
-- ======================================================================

-- 1. Add gender column
ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS gender text CHECK (gender IN ('male','female','other'));

-- 2. Rewrite auto-friend trigger function: only ONE random AI, only for male users, status pending, no auto DM
CREATE OR REPLACE FUNCTION public.auto_friend_ai_bots()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  bot_id uuid;
BEGIN
  IF NEW.is_ai THEN RETURN NEW; END IF;
  IF NEW.gender IS DISTINCT FROM 'male' THEN RETURN NEW; END IF;

  -- Skip if this user already has any partner_request from an AI bot
  IF EXISTS (
    SELECT 1 FROM public.partner_requests pr
    JOIN public.profiles p ON p.id = pr.requester_id
    WHERE pr.addressee_id = NEW.id AND p.is_ai = true
  ) THEN
    RETURN NEW;
  END IF;

  SELECT id INTO bot_id
  FROM public.profiles
  WHERE is_ai = true
  ORDER BY random()
  LIMIT 1;

  IF bot_id IS NULL THEN RETURN NEW; END IF;

  INSERT INTO public.partner_requests(requester_id, addressee_id, status)
    VALUES (bot_id, NEW.id, 'pending')
    ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;

-- 3. Drop old triggers and re-attach on INSERT + gender UPDATE
DROP TRIGGER IF EXISTS auto_friend_ai_bots_trg ON public.profiles;
DROP TRIGGER IF EXISTS trg_auto_friend_ai_bots ON public.profiles;
DROP TRIGGER IF EXISTS auto_friend_ai_bots_after_insert ON public.profiles;

CREATE TRIGGER auto_friend_ai_bots_after_upsert
AFTER INSERT OR UPDATE OF gender ON public.profiles
FOR EACH ROW
EXECUTE FUNCTION public.auto_friend_ai_bots();


-- ======================================================================
-- 20260710114051_041d80de-028d-4bb8-9399-26c211c550ab.sql
-- ======================================================================

-- Clean up legacy AI over-friending: keep at most one AI partner per non-AI user (male only),
-- delete other AI partner_requests and their direct_messages.

WITH keepers AS (
  SELECT DISTINCT ON (pr.addressee_id) pr.id, pr.addressee_id, pr.requester_id
  FROM public.partner_requests pr
  JOIN public.profiles bot ON bot.id = pr.requester_id AND bot.is_ai = true
  JOIN public.profiles usr ON usr.id = pr.addressee_id AND usr.is_ai = false
  WHERE usr.gender = 'male'
  ORDER BY pr.addressee_id, pr.created_at ASC
),
to_delete AS (
  SELECT pr.id, pr.requester_id AS bot_id, pr.addressee_id AS user_id
  FROM public.partner_requests pr
  JOIN public.profiles bot ON bot.id = pr.requester_id AND bot.is_ai = true
  JOIN public.profiles usr ON usr.id = pr.addressee_id AND usr.is_ai = false
  WHERE pr.id NOT IN (SELECT id FROM keepers)
)
DELETE FROM public.direct_messages dm
USING to_delete td
WHERE (dm.sender_id = td.bot_id AND dm.receiver_id = td.user_id)
   OR (dm.sender_id = td.user_id AND dm.receiver_id = td.bot_id);

DELETE FROM public.partner_requests pr
USING public.profiles bot, public.profiles usr
WHERE pr.requester_id = bot.id AND bot.is_ai = true
  AND pr.addressee_id = usr.id AND usr.is_ai = false
  AND pr.id NOT IN (
    SELECT DISTINCT ON (pr2.addressee_id) pr2.id
    FROM public.partner_requests pr2
    JOIN public.profiles b2 ON b2.id = pr2.requester_id AND b2.is_ai = true
    JOIN public.profiles u2 ON u2.id = pr2.addressee_id AND u2.is_ai = false
    WHERE u2.gender = 'male'
    ORDER BY pr2.addressee_id, pr2.created_at ASC
  );


-- ======================================================================
-- 20260712061022_684758d0-4ec4-4b7d-9e6f-afc8aab6067b.sql
-- ======================================================================

CREATE OR REPLACE FUNCTION public.auto_friend_ai_bots()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  bot_id uuid;
BEGIN
  IF NEW.is_ai THEN RETURN NEW; END IF;

  IF TG_OP = 'UPDATE' THEN
    -- If gender switched to female/other, remove any pending AI friend request
    IF NEW.gender IS DISTINCT FROM OLD.gender AND NEW.gender IN ('female','other') THEN
      DELETE FROM public.partner_requests pr
      USING public.profiles p
      WHERE pr.addressee_id = NEW.id
        AND pr.status = 'pending'
        AND pr.requester_id = p.id
        AND p.is_ai = true;
      RETURN NEW;
    END IF;
    -- On update: only continue when gender flips to male (INSERT path handles new users)
    IF NOT (NEW.gender IS DISTINCT FROM OLD.gender AND NEW.gender = 'male') THEN
      RETURN NEW;
    END IF;
  END IF;

  -- Skip if user already has any partner_request from an AI bot
  IF EXISTS (
    SELECT 1 FROM public.partner_requests pr
    JOIN public.profiles p ON p.id = pr.requester_id
    WHERE pr.addressee_id = NEW.id AND p.is_ai = true
  ) THEN
    RETURN NEW;
  END IF;

  SELECT id INTO bot_id
  FROM public.profiles
  WHERE is_ai = true
  ORDER BY random()
  LIMIT 1;

  IF bot_id IS NULL THEN RETURN NEW; END IF;

  INSERT INTO public.partner_requests(requester_id, addressee_id, status)
    VALUES (bot_id, NEW.id, 'pending')
    ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;

-- Backfill: any existing real user without an AI friend request gets one
DO $$
DECLARE
  u record;
  bot_id uuid;
BEGIN
  FOR u IN
    SELECT p.id FROM public.profiles p
    WHERE p.is_ai = false
      AND COALESCE(p.gender, 'male') <> 'female'
      AND COALESCE(p.gender, 'male') <> 'other'
      AND NOT EXISTS (
        SELECT 1 FROM public.partner_requests pr
        JOIN public.profiles bp ON bp.id = pr.requester_id AND bp.is_ai = true
        WHERE pr.addressee_id = p.id
      )
  LOOP
    SELECT id INTO bot_id FROM public.profiles WHERE is_ai = true ORDER BY random() LIMIT 1;
    IF bot_id IS NOT NULL THEN
      INSERT INTO public.partner_requests(requester_id, addressee_id, status)
        VALUES (bot_id, u.id, 'pending')
        ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
END $$;

